package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class PropertyTaxActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Property Tax & Valuation","Fiscal layer linked to the parcel ULPIN.");String u=getIntent().getStringExtra("ulpin");if(u==null)u="24-GJ-GN-0001-00001";DatabaseManager m=new DatabaseManager(this);Cursor t=m.getDatabase().rawQuery("SELECT annual_tax,outstanding_amount,financial_year,last_payment_date,status FROM tax_records WHERE ulpin=?",new String[]{u});try{if(t.moveToFirst()){LinearLayout c=utils.column(this);utils.row(c,this,"Annual tax","₹ "+t.getDouble(0));utils.row(c,this,"Outstanding","₹ "+t.getDouble(1));utils.row(c,this,"Financial year",t.getString(2));utils.row(c,this,"Last payment",t.getString(3));utils.row(c,this,"Status",t.getString(4));utils.addCard(root,c,this);}else root.addView(utils.text(this,"No fiscal record in the demo dataset.",14,utils.MUTED,false));}finally{t.close();}Cursor v=m.getDatabase().rawQuery("SELECT guideline_value,market_reference,unit,valuation_year,source,status FROM valuation_records WHERE ulpin=?",new String[]{u});try{if(v.moveToFirst()){LinearLayout c=utils.column(this);c.addView(utils.text(this,"Valuation Reference",18,utils.TEXT,true));utils.row(c,this,"Guideline value","₹ "+v.getDouble(0));utils.row(c,this,"Market reference","₹ "+v.getDouble(1));utils.row(c,this,"Unit",v.getString(2));utils.row(c,this,"Year",v.getString(3));c.addView(utils.text(this,"Reference dataset only — not a government valuation or transaction quote.",12,utils.MUTED,false));utils.addCard(root,c,this);}}finally{v.close();}utils.setScreenContentView(this, root);}
}
